        case MonsterUnitUberDiablo:
          diablo_family:
          if (nParam == 0xb) {
            return DropHandlerArray + 0x10;
          }
        if (nParam != 10) {
          return DropHandlerArray + nParam;
        }

        return DropHandlerArray + 0x11;
