    killStrc.nMonType1 = 0;
    killStrc.nMonType2 = 0;
    killStrc.nUnitMode = eD2MonsterAnimMode_ns::Skill1;
    uint8_t byAnimMode2 = 'd';
    killStrc.pVictim = pUnit;
